import json
from eda_bridge import execute
from pathlib import Path
q='''if((await eda.dmt_SelectControl.getCurrentDocumentInfo()).uuid!=="497aabae1f192fa8")throw new Error("Wrong PCB");const M=1/0.0254;const layers={TOP:1,BOTTOM:2,OUTLINE:11,MULTI:12};const rules={NO_COMPONENTS:2,NO_WIRES:5,NO_FILLS:6,NO_POURS:7};const ids={holes:[],regions:[]};await eda.pcb_Layer.setTheNumberOfCopperLayers(6);const p=eda.pcb_MathPolygon.createPolygon([M,0,"L",38.8*M,0,"ARC",-90,39.8*M,-M,"L",39.8*M,-38.8*M,"ARC",-90,38.8*M,-39.8*M,"L",M,-39.8*M,"ARC",-90,0,-38.8*M,"L",0,-M,"ARC",-90,M,0]);const o=await eda.pcb_PrimitivePolyline.create("",layers.OUTLINE,p,0.1*M,true);if(!o)throw new Error("Outline failed");ids.outline=o.getState_PrimitiveId();for(const [i,x,y] of [[1,2.5,11],[2,37.3,11],[3,2.5,28.8],[4,37.3,28]]){const h=await eda.pcb_PrimitiveFill.create(layers.MULTI,eda.pcb_MathPolygon.createPolygon(["CIRCLE",x*M,-y*M,1.1*M]),"",0,0,true);ids.holes.push(h.getState_PrimitiveId());for(const layer of [1,2,15,16,17,18]){const reg=await eda.pcb_PrimitiveRegion.create(layer,eda.pcb_MathPolygon.createPolygon(["CIRCLE",x*M,-y*M,2.1*M]),[rules.NO_COMPONENTS,rules.NO_WIRES,rules.NO_FILLS,rules.NO_POURS],"H"+i+"_M2_KEEP_OUT",0.1*M,true);ids.regions.push(reg.getState_PrimitiveId());}}await eda.pcb_Document.save();return {ids,bbox:await eda.pcb_Primitive.getPrimitivesBBox([ids.outline]),layers:await eda.pcb_Layer.getAllLayers()};'''
r=execute(q);Path('hardware/easyeda-pro/pcb-mechanical-created.json').write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf-8');print(r['ids']);print(r['bbox'])
